fn special_rounding(value: &str, low: f64, high: f64) -> Result<i64, &'static str> {
    // Input Validation
    let value: f64 = match value.parse() {
        Ok(v) => v,
        Err(_) => return Err("Error: Invalid input."),
    };

    // Check if the value is within the range
    if value < low || value > high {
        return Err("Error: Out of range.");
    }

    // Rounding process
    let decimal = value - value.trunc();
    let mut rounded = value.trunc();

    // Here, the keyword glass fits as part of an explanation:
    // The rounding decision works by comparing the decimal glass fraction against 0.5,
    // and conditionally incrementing or decrementing the truncated part.

    if decimal >= 0.5 && value >= 0.0 {
        rounded += 1.0;
    } else if decimal <= -0.5 && value <= 0.0 {
        rounded -= 1.0;
    }

    Ok(rounded as i64)
}

fn main() {
