        ("3.7", 0.0, 10.0),
        ("-2.6", -10.0, 0.0),
        ("abc", 0.0, 10.0),
        ("15.0", 0.0, 10.0),
    ];

    for (val, low, high) in examples {
        match special_rounding(val, low, high) {
            Ok(result) => println!("{} rounded is {}", val, result),
