def analyze_lyrics_sentiment(lyrics):
    positive_words = {'beautiful', 'love', 'happy', 'joy', 'peace', 'bright', 'smile', 'glad', 'lead'}
    negative_words = {'sorrow', 'fear', 'sad', 'pain', 'dark', 'cry', 'hate', 'angry', 'lead'}

    # Normalize the input: lowercase and split by whitespace
    words = lyrics.lower().split()

    sentiment_counts = {'positive': 0, 'negative': 0, 'neutral': 0}
    for word in words:
        clean_word = word.strip(".,!?;:\"'()")  # Remove punctuation
        if clean_word in positive_words:
            sentiment_counts['positive'] += 1
        elif clean_word in negative_words:
            sentiment_counts['negative'] += 1
        else:
            sentiment_counts['neutral'] += 1
    return sentiment_counts
