import java.util.HashMap;

public class CharFrequencyCounter {
    public static void main(String[] args) {
        String input = "Hello, World!";

        // *1. Validate Input*
        if (input == null) {
            System.err.println("Error: Input string is null.");
            return;
        }

        // *2. Convert String to Character Array*
        char[] chars = input.toCharArray();

        // *3. Create HashMap to Store Frequencies*
        HashMap<Character, Integer> frequencyMap = new HashMap<>();

        // *4. Iterate Over Character Array and Count Frequencies*
        for (char c : chars) {
            // *5. Handle Unsupported Characters (Example: consider only ASCII)*
            if (c > 127) {
                System.err.println("Warning: Unsupported character encountered: '" + c + "'");
                continue;
            }

            // *6. Update frequency count in HashMap*
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        // *7. Display the frequency counts*
        System.out.println("Character frequencies:");
        for (Character key : frequencyMap.keySet()) {
            System.out.println("'" + key + "' : " + frequencyMap.get(key));
        }

        // *8. Optionally, handle empty input*
        if (chars.length == 0) {
            System.out.println("The input string is empty.");
        }
    }
}
```
This code snippet demonstrates how to transform a *textual sequence* into a *character array*, *count character frequencies* with a *HashMap*, and *handle unsupported characters* and *error cases* gracefully.

